#!/usr/bin/env python3
"""
LLM Context Document Generator - Rule-based Architecture Documentation

Generates PROJECT_ARCHITECTURE.md from analysis results.
Designed for LLM context injection with structured, predictable format.

Usage:
    python context_generator.py arch.json -o PROJECT_ARCHITECTURE.md
    python mapper.py /project --class-nodes | python context_generator.py - -o docs/ARCHITECTURE.md
"""

from __future__ import annotations
import argparse
import json
import sys
from datetime import datetime
from pathlib import Path
from collections import defaultdict
from dataclasses import dataclass, field
from typing import Any


@dataclass
class NodeInfo:
    """Processed node information"""
    id: str
    name: str
    type: str  # module, class, package
    language: str
    layer: int
    path: str
    classes: list[str] = field(default_factory=list)
    functions: list[str] = field(default_factory=list)
    in_degree: int = 0
    out_degree: int = 0


@dataclass
class EdgeInfo:
    """Processed edge information"""
    source: str
    target: str
    type: str
    weight: int = 1
    metadata: dict = field(default_factory=dict)


class LLMContextGenerator:
    """Generate structured LLM context documents from architecture analysis"""
    
    def __init__(self, data: dict):
        self.data = data
        self.nodes: dict[str, NodeInfo] = {}
        self.edges: list[EdgeInfo] = []
        self.metadata = data.get("metadata", {})
        self.analysis = data.get("analysis", {})
        self._parse_data()
    
    def _parse_data(self) -> None:
        """Parse input JSON into structured data"""
        # Parse nodes
        for node in self.data.get("nodes", []):
            node_id = node["id"]
            
            # Extract name from ID
            if "::" in node_id:
                name = node_id.split("::")[-1]
            elif "/" in node_id:
                name = node_id.split("/")[-1]
            else:
                name = node_id
            
            self.nodes[node_id] = NodeInfo(
                id=node_id,
                name=name,
                type=node.get("type", "module"),
                language=node.get("language", "unknown"),
                layer=node.get("layer", 0),
                path=node.get("path", node_id),
                classes=node.get("classes", []),
                functions=node.get("functions", []),
            )
        
        # Parse edges and calculate degrees
        for edge in self.data.get("edges", []):
            self.edges.append(EdgeInfo(
                source=edge["source"],
                target=edge["target"],
                type=edge.get("type", "UNKNOWN"),
                weight=edge.get("weight", 1),
                metadata=edge.get("metadata", {}),
            ))
            
            # Update degrees
            if edge["source"] in self.nodes:
                self.nodes[edge["source"]].out_degree += 1
            if edge["target"] in self.nodes:
                self.nodes[edge["target"]].in_degree += 1
    
    def generate(self, include_mermaid: bool = True) -> str:
        """Generate the full architecture document"""
        sections = [
            self._generate_header(),
            self._generate_overview(),
            self._generate_structure_summary(),
            self._generate_layers(),
            self._generate_hub_analysis(),
            self._generate_critical_paths(),
            self._generate_edge_summary(),
        ]
        
        if include_mermaid:
            sections.append(self._generate_mermaid())
        
        sections.append(self._generate_footer())
        
        return "\n\n".join(filter(None, sections))
    
    def _generate_header(self) -> str:
        """Generate document header"""
        project_root = self.metadata.get("project_root", "Unknown Project")
        project_name = Path(project_root).name if project_root else "Project"
        
        return f"""# PROJECT_ARCHITECTURE.md
> Auto-generated by LLM Context Generator
> Generated: {datetime.now().strftime("%Y-%m-%d %H:%M:%S")}
> Source: {project_root}

---"""

    def _generate_overview(self) -> str:
        """Generate overview section"""
        languages = self.metadata.get("languages", {})
        total_files = self.metadata.get("total_files", len(self.nodes))
        total_edges = self.metadata.get("total_edges", len(self.edges))
        
        # Count by type
        type_counts = defaultdict(int)
        for node in self.nodes.values():
            type_counts[node.type] += 1
        
        lang_str = ", ".join(f"{lang}: {count}" for lang, count in languages.items())
        type_str = ", ".join(f"{t}: {c}" for t, c in sorted(type_counts.items()))
        
        return f"""## Overview

| Metric | Value |
|--------|-------|
| Total Nodes | {total_files} |
| Total Edges | {total_edges} |
| Languages | {lang_str or "N/A"} |
| Node Types | {type_str or "N/A"} |"""

    def _generate_structure_summary(self) -> str:
        """Generate structure summary from analysis"""
        if not self.analysis:
            return ""
        
        max_depth = self.analysis.get("max_depth", 0)
        layer_dist = self.analysis.get("layer_distribution", {})
        edge_types = self.analysis.get("edge_type_breakdown", {})
        
        # Format layer distribution
        layer_str = " → ".join(
            f"L{k}({v})" 
            for k, v in sorted(layer_dist.items(), key=lambda x: int(x[0]))
        )
        
        # Format edge types
        edge_str = ", ".join(f"{t}: {c}" for t, c in edge_types.items())
        
        return f"""## Structure Summary

| Property | Value |
|----------|-------|
| Max Depth | {max_depth} layers |
| Layer Distribution | {layer_str or "N/A"} |
| Edge Types | {edge_str or "N/A"} |"""

    def _generate_layers(self) -> str:
        """Generate nodes by layer section"""
        # Group nodes by layer
        layers: dict[int, list[NodeInfo]] = defaultdict(list)
        for node in self.nodes.values():
            layers[node.layer].append(node)
        
        if not layers:
            return ""
        
        lines = ["## Nodes by Layer"]
        
        # Layer naming convention
        layer_names = {
            0: "Entry Points / UI",
            1: "Controllers / API",
            2: "Services / Business Logic", 
            3: "Repositories / Data Access",
            4: "Database / External",
        }
        
        for layer_num in sorted(layers.keys()):
            if layer_num < 0:
                continue  # Skip unreachable nodes
                
            nodes = layers[layer_num]
            layer_name = layer_names.get(layer_num, f"Layer {layer_num}")
            
            lines.append(f"\n### Layer {layer_num}: {layer_name}")
            lines.append(f"*{len(nodes)} nodes*\n")
            
            # Group by type within layer
            by_type: dict[str, list[NodeInfo]] = defaultdict(list)
            for node in nodes:
                by_type[node.type].append(node)
            
            for node_type, type_nodes in sorted(by_type.items()):
                if len(by_type) > 1:
                    lines.append(f"**{node_type.title()}s:**")
                
                for node in sorted(type_nodes, key=lambda x: x.name):
                    # Build description
                    desc_parts = []
                    if node.classes:
                        desc_parts.append(f"classes: {', '.join(node.classes[:3])}")
                    if node.functions:
                        desc_parts.append(f"functions: {', '.join(node.functions[:3])}")
                    
                    desc = f" ({'; '.join(desc_parts)})" if desc_parts else ""
                    lines.append(f"- `{node.name}`{desc}")
        
        return "\n".join(lines)

    def _generate_hub_analysis(self) -> str:
        """Generate hub node analysis"""
        if not self.analysis:
            return ""
        
        hub_nodes = self.analysis.get("hub_nodes", [])
        connector_nodes = self.analysis.get("connector_nodes", [])
        entry_points = self.analysis.get("entry_points", [])
        leaf_nodes = self.analysis.get("leaf_nodes", [])
        
        lines = ["## Key Nodes"]
        
        # Entry points
        if entry_points:
            lines.append("\n### Entry Points (no incoming dependencies)")
            for ep in entry_points[:5]:
                lines.append(f"- `{ep}`")
        
        # Hub nodes (most depended upon)
        if hub_nodes:
            lines.append("\n### Hub Nodes (most depended upon)")
            lines.append("| Node | In-Degree | Impact |")
            lines.append("|------|-----------|--------|")
            for hub in hub_nodes[:5]:
                node_id = hub.get("id", hub) if isinstance(hub, dict) else hub
                in_deg = hub.get("in_degree", "?") if isinstance(hub, dict) else "?"
                impact = "🔴 Critical" if int(in_deg) >= 3 else "🟡 Important"
                name = node_id.split("::")[-1] if "::" in node_id else node_id.split("/")[-1]
                lines.append(f"| `{name}` | {in_deg} | {impact} |")
        
        # Connector nodes (most dependencies)
        if connector_nodes:
            lines.append("\n### Connector Nodes (most outgoing dependencies)")
            lines.append("| Node | Out-Degree |")
            lines.append("|------|------------|")
            for conn in connector_nodes[:5]:
                node_id = conn.get("id", conn) if isinstance(conn, dict) else conn
                out_deg = conn.get("out_degree", "?") if isinstance(conn, dict) else "?"
                name = node_id.split("::")[-1] if "::" in node_id else node_id.split("/")[-1]
                lines.append(f"| `{name}` | {out_deg} |")
        
        # Leaf nodes
        if leaf_nodes:
            lines.append("\n### Leaf Nodes (no outgoing dependencies)")
            lines.append("*Utilities, helpers, base classes:*")
            for leaf in leaf_nodes[:5]:
                name = leaf.split("::")[-1] if "::" in leaf else leaf.split("/")[-1]
                lines.append(f"- `{name}`")
        
        return "\n".join(lines)

    def _generate_critical_paths(self) -> str:
        """Generate critical paths analysis"""
        # Find paths from entry points to leaf nodes
        entry_points = self.analysis.get("entry_points", [])
        leaf_nodes = set(self.analysis.get("leaf_nodes", []))
        
        if not entry_points or not leaf_nodes:
            return ""
        
        # Build adjacency for path finding
        adj: dict[str, list[str]] = defaultdict(list)
        for edge in self.edges:
            adj[edge.source].append(edge.target)
        
        # Find sample paths (simplified BFS)
        paths = []
        for entry in entry_points[:2]:
            path = self._find_path_to_leaf(entry, leaf_nodes, adj)
            if path and len(path) > 1:
                paths.append(path)
        
        if not paths:
            return ""
        
        lines = ["## Critical Paths"]
        lines.append("*Sample dependency chains from entry to leaf:*\n")
        
        for i, path in enumerate(paths[:3], 1):
            path_names = []
            for node_id in path:
                name = node_id.split("::")[-1] if "::" in node_id else node_id.split("/")[-1]
                path_names.append(f"`{name}`")
            lines.append(f"{i}. {' → '.join(path_names)}")
        
        return "\n".join(lines)
    
    def _find_path_to_leaf(
        self, 
        start: str, 
        leaves: set[str], 
        adj: dict[str, list[str]],
        max_depth: int = 10
    ) -> list[str]:
        """Find a path from start to any leaf node"""
        from collections import deque
        
        queue = deque([(start, [start])])
        visited = {start}
        
        while queue:
            current, path = queue.popleft()
            
            if current in leaves:
                return path
            
            if len(path) >= max_depth:
                continue
            
            for neighbor in adj.get(current, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, path + [neighbor]))
        
        return []

    def _generate_edge_summary(self) -> str:
        """Generate edge summary table"""
        if not self.edges:
            return ""
        
        # Group edges by type
        by_type: dict[str, list[EdgeInfo]] = defaultdict(list)
        for edge in self.edges:
            by_type[edge.type].append(edge)
        
        lines = ["## Dependency Summary"]
        
        for edge_type, edges in sorted(by_type.items()):
            lines.append(f"\n### {edge_type} ({len(edges)} edges)")
            
            # Show top edges by weight or frequency
            lines.append("| Source | Target | Details |")
            lines.append("|--------|--------|---------|")
            
            for edge in sorted(edges, key=lambda x: -x.weight)[:10]:
                src_name = edge.source.split("::")[-1] if "::" in edge.source else edge.source.split("/")[-1]
                tgt_name = edge.target.split("::")[-1] if "::" in edge.target else edge.target.split("/")[-1]
                
                details = []
                if edge.weight > 1:
                    details.append(f"weight: {edge.weight}")
                if edge.metadata:
                    if "imported" in edge.metadata:
                        imported = edge.metadata["imported"]
                        if isinstance(imported, list):
                            details.append(f"imports: {', '.join(imported[:2])}")
                    if "internal" in edge.metadata:
                        details.append("internal" if edge.metadata["internal"] else "external")
                
                detail_str = "; ".join(details) if details else "-"
                lines.append(f"| `{src_name}` | `{tgt_name}` | {detail_str} |")
        
        return "\n".join(lines)

    def _generate_mermaid(self) -> str:
        """Generate Mermaid diagram"""
        # Filter out package nodes for cleaner diagram
        display_nodes = {k: v for k, v in self.nodes.items() 
                        if not k.startswith("[pkg]") and v.type != "package"}
        
        if len(display_nodes) > 30:
            return "## Diagram\n*Skipped: Too many nodes (>30) for readable diagram*"
        
        lines = ["## Diagram", "```mermaid", "flowchart TD"]
        
        # Add subgraphs by layer
        layers: dict[int, list[str]] = defaultdict(list)
        for node_id, node in display_nodes.items():
            layers[node.layer].append(node_id)
        
        # Node ID sanitization for Mermaid
        def sanitize(s: str) -> str:
            # Remove problematic characters
            result = s.replace("/", "_").replace("::", "__").replace(".", "_")
            result = result.replace("-", "_").replace("[", "").replace("]", "")
            result = result.replace(" ", "_")
            # Ensure starts with letter
            if result and result[0].isdigit():
                result = "n" + result
            return result
        
        def short_name(s: str) -> str:
            if "::" in s:
                return s.split("::")[-1]
            name = s.split("/")[-1]
            # Remove extension
            for ext in [".py", ".ts", ".tsx", ".js", ".jsx"]:
                if name.endswith(ext):
                    name = name[:-len(ext)]
                    break
            return name
        
        # Track which nodes we've defined
        defined_nodes = set()
        
        # Add nodes by layer
        for layer_num in sorted(layers.keys()):
            if layer_num < 0:
                continue
            node_ids = layers[layer_num]
            lines.append(f"    subgraph L{layer_num}[Layer {layer_num}]")
            for node_id in sorted(node_ids):
                safe_id = sanitize(node_id)
                name = short_name(node_id)
                lines.append(f"        {safe_id}[{name}]")
                defined_nodes.add(node_id)
            lines.append("    end")
        
        # Add edges (only for defined nodes)
        edge_count = 0
        for edge in self.edges:
            if edge_count >= 40:  # Limit edges
                break
            
            # Skip package edges and edges to undefined nodes
            if edge.source.startswith("[pkg]") or edge.target.startswith("[pkg]"):
                continue
            if edge.source not in defined_nodes and edge.target not in defined_nodes:
                continue
                
            src = sanitize(edge.source)
            tgt = sanitize(edge.target)
            
            # Edge style by type
            if edge.type == "INHERITANCE":
                lines.append(f"    {src} -.->|extends| {tgt}")
            elif edge.type == "FUNCTION_CALL":
                lines.append(f"    {src} -->|call| {tgt}")
            else:
                lines.append(f"    {src} --> {tgt}")
            
            edge_count += 1
        
        lines.append("```")
        return "\n".join(lines)

    def _generate_footer(self) -> str:
        """Generate document footer"""
        return """---
*This document is auto-generated. Do not edit manually.*
*Regenerate with: `python context_generator.py <input.json> -o PROJECT_ARCHITECTURE.md`*"""


def load_input(input_path: str) -> dict:
    """Load JSON from file or stdin"""
    if input_path == "-":
        return json.loads(sys.stdin.read())
    else:
        with open(input_path) as f:
            return json.load(f)


def main():
    parser = argparse.ArgumentParser(
        description="Generate LLM context document from architecture analysis",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
    # From mapper output
    python context_generator.py arch.json -o PROJECT_ARCHITECTURE.md
    
    # Pipe from mapper
    python mapper.py /project --class-nodes | python context_generator.py - -o docs/ARCH.md
    
    # Without Mermaid diagram
    python context_generator.py arch.json --no-mermaid
        """
    )
    
    parser.add_argument(
        "input",
        help="Analysis JSON file or '-' for stdin"
    )
    
    parser.add_argument(
        "-o", "--output",
        help="Output markdown file (default: stdout)"
    )
    
    parser.add_argument(
        "--no-mermaid",
        action="store_true",
        help="Skip Mermaid diagram generation"
    )
    
    args = parser.parse_args()
    
    # Load input
    try:
        data = load_input(args.input)
    except Exception as e:
        print(f"Error loading input: {e}", file=sys.stderr)
        sys.exit(1)
    
    # Generate document
    generator = LLMContextGenerator(data)
    document = generator.generate(include_mermaid=not args.no_mermaid)
    
    # Output
    if args.output:
        Path(args.output).write_text(document, encoding="utf-8")
        print(f"✓ Generated: {args.output}", file=sys.stderr)
    else:
        print(document)


if __name__ == "__main__":
    main()
